 if(path==='/v1/slim/rpc'&&req.method==='POST'){const b=await body(req);if(!contract[b.module]?.includes(b.method))throw error(403,'Operação fora do contrato.');if(b.module==='@/lib/permissions-core.functions'&&b.method==='getMyPermissions'){const m=membership(store,user),scope=m.permissions.includes('allLeads')?'all':'assigned',entities=ids=>Object.fromEntries(ids.map(id=>[id,Object.fromEntries(['create','view','edit','delete','export'].map(action=>[action,scope]))]));return send(res,200,{effective:{role:m.role,full:m.role==='owner',permissions:{modules:{crm:{enabled:m.permissions.includes('clients')||m.permissions.includes('pipeline'),entities:entities(['leads','contacts','companies','tasks','products']),pipelines:visibleWorkspace(store,user).funnels.map(f=>f.id),stages:[]},inbox:{enabled:m.permissions.includes('inbox'),entities:entities(['conversations','templates']),pipelines:visibleWorkspace(store,user).funnels.map(f=>f.id),stages:[]}}}}});}if(b.module==='@/lib/crm-audiences.functions'&&audienceMethods.has(b.method))return send(res,200,await audienceRPC(store,user,b.method,b.data));if(inboxMethods.has(b.method)&&['@/lib/leads.functions','@/lib/leads.functions.legacy','@/lib/whatsapp-groups.functions','@/lib/inbox-labels.functions'].includes(b.module))return send(res,200,await inboxRPC(store,user,evolution,b.method,b.data));const result=await rpc(scopedWorkspaceStore(store,user,b.module,b.method,b.data),ws,b.module,b.method,b.data);return send(res,200,result);}
